def _batch_online_atomic(self, items, now_ms):
    """原子逐项演算：任一失败即停止，回滚已演算项，未演算项记“回滚”。

    失败项记异常类名；其前已成功项回滚（置下线、期限 0、释放地址租约，
    与下线同效），其后未演算项不演算、记“回滚”。老化、认证计数与退避
    保留。返回 (rendered, commit)；全成功 commit=True。
    """
    rendered = [None] * len(items)
    committed = []
    failure_index = None
    for index, triple in enumerate(items):
        try:
            rendered[index] = self._batch_online_attempt(triple, now_ms)
        except (
            AuthError,
            ResourceError,
            StateError,
            KeyError,
            BackendError,
        ) as exc:
            failure_index = index
            rendered[index] = {"会话": triple[0], "结果": type(exc).__name__}
            break
        committed.append(triple[0])

    if failure_index is None:
        return rendered, True

    # 回滚已演算成功项：置下线、期限 0、释放其地址租约（动态址回堆、
    # 静态址仅退租）；失败项本身未落库，未演算项从未演算。
    for sid in committed:
        session = self._sessions[sid]
        session["state"] = _STATE_OFFLINE
        session["deadline"] = 0
        self._release(session)
    for index in range(failure_index + 1, len(items)):
        rendered[index] = {"会话": items[index][0], "结果": _BATCH_ROLLBACK}
    return rendered, False

